// Builds the pgTAP parity test for public.offset_point from tests/fixtures/geo.json, so the SQL
// function and destination() in core/geo.js move a point the same way (BR-LST-004).
// Regenerate after changing the fixture:
//   node tests/fixtures/geo-pgtap.js > supabase/tests/database/20_offset_point_parity.sql
// tests/unit/geo.test.js fails if the generated file is out of date.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const GEO_PARITY_TEST_PATH = 'supabase/tests/database/20_offset_point_parity.sql';

// 1e-9 degrees is about 0.1 mm: both sides run the same double-precision formula.
const TOLERANCE = 1e-9;

export function geoPgtap(fixture) {
  const lines = [
    '-- GENERATED by tests/fixtures/geo-pgtap.js from tests/fixtures/geo.json. Do not edit.',
    '-- Parity: public.offset_point (SQL) moves a point like destination() in core/geo.js (BR-LST-004).',
    'begin;',
    'create extension if not exists pgtap with schema extensions;',
    `select plan(${fixture.cases.length});`,
    '',
  ];
  for (const c of fixture.cases) {
    const call = `public.offset_point(${c.from.lat}, ${c.from.lng}, ${c.km}, ${c.bearing})`;
    lines.push(
      `select ok((select abs(lat - (${c.to.lat})) < ${TOLERANCE} and abs(lng - (${c.to.lng})) < ${TOLERANCE} from ${call}),`,
      `  'parity: ${c.name.replaceAll("'", "''")}');`,
    );
  }
  lines.push('', 'select * from finish();', 'rollback;', '');
  return lines.join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const fixture = JSON.parse(readFileSync(new URL('./geo.json', import.meta.url), 'utf8'));
  process.stdout.write(geoPgtap(fixture));
}
